// And groups predicates with the AND operator between them.
func And(predicates ...predicate.TradeIn) predicate.TradeIn {
	return predicate.TradeIn(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.TradeIn) predicate.TradeIn {
	return predicate.TradeIn(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.TradeIn) predicate.TradeIn {
	return predicate.TradeIn(sql.NotPredicates(p))
}
